// src/api/partAPI.js
import axios_api from "./axios";
import { apiPath } from "./config";

const host = apiPath("/buyer/partlist");

// 전체 조회
export const getPartList = async () => {
  const res = await axios_api.get(host);
  return res.data;
};

// 등록
export const createPartList = async (formData) => {
  const payload = {
    partCode: String(formData.partCode || "").trim(),
    partName: String(formData.partName || "").trim(),
    partSpec: String(formData.partSpec || "").trim(),
    partPrice: Number(formData.partPrice ?? 0),
    // 셀렉트의 value가 buyerNo.
    buyerNo: Number(formData.buyerNo ?? formData.buyerComp) || null,
  };

  if (!payload.buyerNo) {
    throw new Error("구매처(buyerNo) 선택은 필수입니다.");
  }

  const res = await axios_api.post(host, payload);
  return res.data;
};

// 수정
export const updatePartList = async (formData) => {
  const partNo = Number(formData.partNo);
  if (!partNo) throw new Error("partNo가 없습니다.");

  const payload = {
    partCode: String(formData.partCode || "").trim(),
    partName: String(formData.partName || "").trim(),
    partSpec: String(formData.partSpec || "").trim(),
    partPrice: Number(formData.partPrice ?? 0),
    buyerNo: Number(formData.buyerNo ?? formData.buyerComp) || null,
  };

  if (!payload.buyerNo) {
    throw new Error("구매처(buyerNo) 선택은 필수입니다.");
  }

  const res = await axios_api.put(apiPath(`/buyer/partlist/${partNo}`), payload);
  return res.data;
};

// 삭제
export const deletePartList = async (partNo) => {
  const res = await axios_api.delete(apiPath(`/buyer/partlist/${partNo}`));
  return res.data;
};
